<?php require '../config.php'; $a=require_admin();$tab=$_GET['tab']??'dashboard';$msg=getflash();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';if($action==='key'){$days=(int)$_POST['days'];$count=min(50,max(1,(int)$_POST['count']));for($i=0;$i<$count;$i++){do{$code='FLY-'.strtoupper(bin2hex(random_bytes(2))).'-'.strtoupper(bin2hex(random_bytes(2))).'-'.strtoupper(bin2hex(random_bytes(2)));$q=$pdo->prepare('SELECT id FROM keys WHERE code=?');$q->execute([$code]);}while($q->fetch());$q=$pdo->prepare('INSERT INTO keys(code,days,created_by,created_at) VALUES(?,?,?,?)');$q->execute([$code,$days,$a['id'],time()]);}flash("Создано ключей: $count");header('Location: ?tab=keys');exit;}if($action==='app'){ $id=(int)$_POST['id'];$status=$_POST['status']==='approved'?'approved':'rejected';$q=$pdo->prepare('UPDATE applications SET status=? WHERE id=?');$q->execute([$status,$id]);flash('Заявка обновлена.');header('Location: ?tab=applications');exit;}}
$keys=$pdo->query('SELECT k.*,u.username FROM keys k LEFT JOIN users u ON u.id=k.used_by ORDER BY k.id DESC LIMIT 100')->fetchAll();$apps=$pdo->query('SELECT a.*,u.username FROM applications a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC')->fetchAll();$users=$pdo->query('SELECT id,username,email,role,plan,plan_expires,created_at FROM users ORDER BY id DESC LIMIT 200')->fetchAll();?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin — Fly Client</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="wrap"><header class="nav"><a class="brand" href="../">FLY<span>.</span>ADMIN</a><a class="btn" href="../dashboard.php">Назад</a></header><div class="adminnav"><a class="btn" href="?tab=dashboard">Обзор</a><a class="btn" href="?tab=keys">Ключи</a><a class="btn" href="?tab=applications">Заявки</a><a class="btn" href="?tab=users">Пользователи</a></div><?php if($msg):?><div class="notice success"><?=e($msg)?></div><?php endif;?><?php if($tab==='dashboard'):?><div class="grid3"><div class="card"><div class="muted">Пользователей</div><h2><?=count($users)?></h2></div><div class="card"><div class="muted">Заявок</div><h2><?=count($apps)?></h2></div><div class="card"><div class="muted">Ключей</div><h2><?=count($keys)?></h2></div></div><?php elseif($tab==='keys'):?><div class="card"><h2>Создать ключи</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="key"><select class="input" name="days"><option value="30">30 дней</option><option value="180">180 дней</option><option value="365">1 год</option><option value="0">Навсегда</option></select><input class="input" type="number" name="count" min="1" max="50" value="1"><button class="btn primary">Создать</button></form></div><div class="card" style="margin-top:16px"><h2>Ключи</h2><table class="table"><tr><th>Ключ</th><th>Срок</th><th>Статус</th></tr><?php foreach($keys as $k):?><tr><td><?=e($k['code'])?></td><td><?=e(plan_name((int)$k['days']))?></td><td><?=$k['used_by']?'Использован: '.e($k['username']):'Свободен'?></td></tr><?php endforeach;?></table></div><?php elseif($tab==='applications'):?><div class="card"><h2>Заявки</h2><table class="table"><tr><th>Тип</th><th>Пользователь</th><th>Данные</th><th>Статус</th><th></th></tr><?php foreach($apps as $x):?><tr><td><?=e($x['type'])?></td><td><?=e($x['username'])?></td><td>Возраст: <?=e($x['age'])?><br>Discord: <?=e($x['discord'])?><br>VK: <?=e($x['vk'])?></td><td><?=e($x['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="app"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn" name="status" value="approved">Одобрить</button> <button class="btn" name="status" value="rejected">Отклонить</button></form></td></tr><?php endforeach;?></table></div><?php else:?><div class="card"><h2>Пользователи</h2><table class="table"><tr><th>Ник</th><th>Email</th><th>Роль</th><th>План</th></tr><?php foreach($users as $x):?><tr><td><?=e($x['username'])?></td><td><?=e($x['email'])?></td><td><?=e($x['role'])?></td><td><?=e($x['plan'])?></td></tr><?php endforeach;?></table></div><?php endif;?></div></body></html>
